{{term:async/await}} 让{{term:异步}}代码看起来像同步代码——{{term:async}} 声明{{term:异步}}{{term:函数}}，{{term:await}} 等待 {{term:Promise}} 完成再继续。就像指挥等待独奏家完成华彩乐段再继续指挥——表面是同步的等待，实际是{{term:异步}}的完成。

```js
// Promise 写法
function getMusicInfo() {
  return fetchUser('小明')
    .then(user => fetchFavorites(user.id))
    .then(favs => console.log(favs))
}
// async/await 写法
async function getMusicInfo() {
  const user = await fetchUser('小明')
  const favs = await fetchFavorites(user.id)
  console.log(favs)
}
```

用 {{term:async/await}} 时，错误处理回到了熟悉的 {{term:try/catch}}：

```js
async function loadMusicData() {
  try {
    const user = await fetchUser('小明')
    const favs = await fetchFavorites(user.id)
    const details = await fetchDetails(favs[0].id)
    console.log('加载成功：', details)
  } catch (error) {
    console.log('加载失败：', error.message)
    // 可以在这里显示友好的错误提示
  }
}
```

这就是为什么学错误处理（上一章）很重要——{{term:async/await}} 中 {{term:try/catch}} 是最佳实践。

::::step{purpose="{{term:async/await}} 让{{term:异步}}代码读起来像同步代码——从上到下、从左到右。{{term:await}} 会暂停当前{{term:函数}}的执行等待 {{term:Promise}} 完成，但不阻塞主线程。就像指挥等独奏家完成华彩乐段——整个乐团在等，但不是僵住，而是准备好了随时接上。" expected="concert {{term:变量}}得到 { {{term:id}}: \"c001\", {{term:title}}: \"维也纳新年音乐会\", place: \"金色大厅\" } 对象。"}
用 {{term:async}} {{term:function}} 声明 loadConcert，内部用 {{term:const}} concert = {{term:await}} fetchConcert() 获取演出信息
::::

::::step{purpose="{{term:await}} 返回的是 {{term:Promise}} 的\"兑现值\"——不需要 .then() {{term:回调}}了。这里你会直观地感受到 {{term:async/await}} 相比 {{term:Promise}} 链的优势：数据直接赋值给{{term:变量}}，下一行就能用，逻辑流线性的。" expected="program {{term:变量}}得到 { concertId: \"c001\", pieces: [\"蓝色多瑙河\", \"拉德茨基进行曲\"] } 对象。"}
用 {{term:const}} program = {{term:await}} fetchProgram(concert.{{term:id}}) 获取曲目单
::::

```js
async function loadConcert() {
  try {
    const concert = await fetchConcert()
    const program = await fetchProgram(concert.id)
    return { concert, program }
  } catch (e) {
    console.log('加载出错：', e.message)
    return null
  }
}
```

